/* Promisory UX prototype. All data and actions are examples held in memory. */
(function () {
'use strict';
var data=window.PROMISORY_DEMO;
var state={view:'overview',selectedPhase:'definition',hierarchy:'native',requirementChanged:false,selected:'PM-101',role:'manager',filter:'all',search:'',delayed:false,sourceRevision:1,proposal:null,reviewed:false,rovo:false,selectedNode:'task',commitments:JSON.parse(JSON.stringify(data.commitments))};
var people={};data.people.forEach(function(p){people[p.id]=p;});
var labels={ON_TRACK:'On track',WATCH:'Watch',AT_RISK:'At risk',BREACHED:'Deadline missed',UNKNOWN:'Incomplete',FULFILLED:'Verified',DRAFT:'Draft',REVIEWED:'Review recorded'};
var symbols={ON_TRACK:'✓',WATCH:'◷',AT_RISK:'!',BREACHED:'!',UNKNOWN:'?',FULFILLED:'✓',DRAFT:'○',REVIEWED:'✓'};
function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function el(id){return document.getElementById(id);}
function date(x){if(!x)return 'Not set';return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(x+'T12:00:00Z'));}
function status(c){var s=c.lifecycle==='FULFILLED'?'FULFILLED':c.lifecycle==='DRAFT'?'DRAFT':c.health;return '<span class="status '+s+'"><span class="status-icon" aria-hidden="true">'+symbols[s]+'</span>'+labels[s]+'</span>';}
function selected(){return state.commitments.find(function(c){return c.id===state.selected;})||state.commitments[0];}
function toast(message){var t=el('toast');t.textContent=message;t.classList.add('visible');clearTimeout(window.promisoryToastTimer);window.promisoryToastTimer=setTimeout(function(){t.classList.remove('visible');},4300);}
function setView(v){state.view=v;render();}
function roleItems(){var rows=state.commitments;if(state.role==='engineer')rows=rows.filter(function(c){return c.workIds.indexOf('task')>=0;});if(state.role==='account')rows=rows.filter(function(c){return c.beneficiary==='Northstar Retail';});if(state.role==='lead')rows=rows.filter(function(c){return c.owner==='leah'||c.workIds.indexOf('task')>=0;});return rows;}
function render(){
var active=roleItems().filter(function(c){return c.lifecycle==='ACTIVE';}).length;
var risk=roleItems().filter(function(c){return c.lifecycle==='ACTIVE'&&c.health==='AT_RISK';}).length;
el('active-count').textContent=active;el('risk-count').textContent=risk;var verified=roleItems().filter(function(c){return c.lifecycle==='FULFILLED';}).length;el('verified-count').textContent=verified;el('verified-caption').textContent=verified?verified+' completed before its deadline':'No verified outcome in this view';
el('risk-caption').textContent=risk?'One confirmed dependency path':'No confirmed delivery blocker';
el('review-count').textContent=state.proposal&&!state.reviewed?'1':'0';
el('simulate').textContent=state.delayed?'Reset example scenario':'Simulate dependency delay';
var titles={lifecycle:['Connect intent to delivery.','Product direction, Confluence evidence, delivery work, and outcomes stay connected.'],overview:['Keep the launch in view.','See what changed, who is responsible, and what needs to happen next.'],map:['Follow the impact.','Real hierarchy and typed dependencies connect work to commitments.'],reviews:['Make the next decision clear.','Review the exact change before any execution authority is requested.'],evidence:['Know what supports the promise.','Source freshness, review records, and verified outcomes stay distinct.']};
el('page-title').textContent=state.role==='engineer'&&state.view==='overview'?'See what your work supports.':titles[state.view][0];
el('page-subtitle').textContent=titles[state.view][1];
document.querySelectorAll('.nav-item').forEach(function(b){var on=b.dataset.view===state.view;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
var notice=el('change-notice');notice.classList.toggle('warn',state.delayed);
notice.innerHTML=state.delayed?'<span class="change-icon" aria-hidden="true">!</span><div><strong>A dependency now threatens Merchant Launch.</strong><p>MX-137 reopened. Its 24 Nov target falls after the 20 Nov customer commitment.</p></div><button class="text-button" id="notice-trace">Trace impact →</button>':'<span class="change-icon" aria-hidden="true">✓</span><div><strong>Active example commitments have confirmed owners.</strong><p>One handover still needs fresh evidence. Inspect the work map or simulate a changed dependency.</p></div><button class="text-button" id="notice-trace">Open work map →</button>';
if(state.requirementChanged&&!state.delayed){notice.classList.add('warn');notice.innerHTML='<span class="change-icon" aria-hidden="true">!</span><div><strong>Requirement REQ-07 needs reassessment.</strong><p>PRD v4 differs from the mapped v3. Release-readiness applicability is stale.</p></div><button class="text-button" id="notice-trace">Inspect impact →</button>';}
el('notice-trace').addEventListener('click',function(){setView('map');});
if(state.view==='overview')renderOverview();else if(state.view==='lifecycle')renderLifecycle();else if(state.view==='map')renderMap();else if(state.view==='reviews')renderReviews();else renderEvidence();
renderDetail();
}
function renderOverview(){
el('view-content').innerHTML='<div class="panel-header"><h2>Your commitments</h2><p>'+esc({manager:'The delivery manager view',lead:'The team lead view',engineer:'Work assigned to the example engineer',account:'Customer-facing commitments'}[state.role])+' · '+roleItems().length+' visible records</p></div><div class="toolbar"><div class="search-field"><label for="commitment-search">Find a commitment</label><input id="commitment-search" type="search" placeholder="Find a commitment..." value="'+esc(state.search)+'"></div><label for="health-filter" class="sr-only">Filter commitment health</label><select id="health-filter" class="filter-select"><option value="all">All states</option><option value="attention">Needs attention</option><option value="verified">Verified outcomes</option></select></div><table class="commit-table"><thead><tr><th scope="col">COMMITMENT</th><th scope="col">DUE</th><th scope="col">STATE</th></tr></thead><tbody id="commitment-rows"></tbody></table><div id="search-empty" class="empty" hidden><h3>No matching commitments</h3><p>Try a different search or health filter.</p></div><div class="table-footer"><span id="visible-count" aria-live="polite"></span><span>Times use each agreed zone</span></div>';
el('health-filter').value=state.filter;
el('commitment-search').addEventListener('input',function(e){state.search=e.target.value;renderRows();});
el('health-filter').addEventListener('change',function(e){state.filter=e.target.value;renderRows();});
renderRows();
}
function renderRows(){
var rows=roleItems().filter(function(c){var matches=(c.title+' '+c.id+' '+c.beneficiary).toLowerCase().indexOf(state.search.toLowerCase())>=0;var filter=state.filter==='all'||(state.filter==='attention'&&['AT_RISK','UNKNOWN','WATCH'].indexOf(c.health)>=0&&c.lifecycle==='ACTIVE')||(state.filter==='verified'&&c.lifecycle==='FULFILLED');return matches&&filter;});
el('commitment-rows').innerHTML=rows.map(function(c){return '<tr class="'+(c.id===state.selected?'selected':'')+'"><td><button class="commit-link" data-commitment="'+esc(c.id)+'">'+esc(c.title)+'</button><span class="row-sub"><span class="key">'+esc(c.id)+'</span> · '+esc(people[c.owner].name)+'</span></td><td><span class="due-date">'+date(c.dueDate)+'</span><span class="row-sub">'+esc(c.cutoffTime||'17:00')+'</span></td><td>'+status(c)+'<span class="row-sub">'+(c.lifecycle==='DRAFT'?'Owner acceptance pending':c.coverage==='INCOMPLETE'?'Fresh evidence needed':c.lifecycle==='FULFILLED'?'Outcome confirmed':'Sources checked')+'</span></td></tr>';}).join('');
el('search-empty').hidden=rows.length>0;el('visible-count').textContent=rows.length+' of '+roleItems().length+' records';
document.querySelectorAll('[data-commitment]').forEach(function(b){b.addEventListener('click',function(){state.selected=b.dataset.commitment;state.rovo=false;renderRows();renderDetail();document.querySelector('[data-commitment="'+state.selected+'"]').focus();});});
}
function renderDetail(){
var c=selected(),p=people[c.owner];
var sources=c.lifecycle==='DRAFT'?'<div class="evidence-mini"><strong>No evidence attached</strong><span>Link sources and obtain owner acceptance before activation.</span></div>':c.id==='PM-101'?'<div class="evidence-mini"><strong>MX-137 · Duplicate onboarding events</strong><span>'+ (state.delayed?'Reopened · target 24 Nov':'Resolved · checked in this example')+'</span></div><div class="evidence-mini"><strong>Merchant launch agreement</strong><span>Example source · version 3 · owner confirmed</span></div>':'<div class="evidence-mini"><strong>'+ (c.coverage==='INCOMPLETE'?'Handover evidence unavailable':'Example acceptance record')+'</strong><span>'+ (c.coverage==='INCOMPLETE'?'Context is incomplete; do not assume success.':'Illustrative source reference only')+'</span></div>';
if(c.id==='PM-101')sources+='<div class="evidence-mini"><strong>REQ-07 · Merchant activation PRD</strong><span>Mapped v3 · current v'+(state.requirementChanged?'4 · reassessment needed':'3 · example Confluence source')+'</span></div>';
var rovo='';
if(state.rovo)rovo='<div class="rovo-sample"><span class="sample-label">Example Rovo exchange · not connected</span><p><strong>What needs attention?</strong></p><p>'+ (c.lifecycle==='DRAFT'?'This draft needs the selected owner to accept it. Link current evidence before activating or assessing the commitment.':c.id==='PM-101'?(state.delayed?'MX-137 blocks MX-121, which implements story MX-110 and supports the launch commitment. REQ-07 connects this work to the self-service initiative and product objective. The bug target is 24 Nov; the promise remains 20 Nov. Maya coordinates the response, Leah owns delivery, and Owen owns the bug.':(state.requirementChanged?'REQ-07 changed from mapped PRD v3 to current v4. Review the requirement and release-readiness basis before treating the old evidence as applicable.':'The launch is approaching its deadline. The example blocker is resolved, but production evidence and designated customer acceptance are still required.')):c.coverage==='INCOMPLETE'?'The handover has an owner, but its evidence is incomplete. Ask the support owner for a current acceptance record.':'Use the agreed acceptance conditions to determine the next evidence needed. A completed task alone does not establish this outcome.')+'</p><div class="source-tags"><span>'+esc(c.id)+'</span>'+(c.id==='PM-101'?'<span>Agreement v3</span>':'')+'<span>Example context</span>'+(c.id==='PM-101'?'<span>MX-137</span>':'')+'</div></div>';
el('detail-panel').innerHTML='<div class="detail-top"><div class="detail-eyebrow"><span class="key">'+esc(c.id)+' · COMMITMENT</span>'+status(c)+'</div><h2>'+esc(c.title)+'</h2><p>For '+esc(c.beneficiary)+'</p>'+ (c.lifecycle==='DRAFT'?'<p>'+ (c.watching?'Watching this example draft':'Not on your example watch list')+'</p>':'')+'</div><div class="detail-body"><div class="meta-row"><span>Accountable owner</span><span class="person"><span class="avatar">'+p.initials+'</span>'+esc(p.name)+'</span></div><div class="meta-row"><span>Agreed deadline</span><strong>'+date(c.dueDate)+' · '+esc(c.cutoffTime||'17:00')+'</strong></div><div class="meta-row"><span>Time zone</span><span>'+esc(c.timeZone||'Europe/Stockholm')+'</span></div><div class="detail-divider"></div><p class="small-label">What fulfillment means</p><p class="acceptance">'+esc(c.acceptance)+'</p><div class="detail-divider"></div><p class="small-label">Evidence in context</p>'+sources+''+(c.id==='PM-101'?'<div class="avatar-stack"><span class="avatar">MC</span><span class="avatar">LO</span><span class="avatar">OR</span><span>Accountable · delivery · engineering</span></div>':'<div class="avatar-stack"><span class="avatar">'+p.initials+'</span><span>Accountable owner'+(c.lifecycle==='DRAFT'?' · acceptance pending':' confirmed')+'</span></div>')+'<div class="detail-actions"><button id="detail-impact" class="button secondary">'+(c.id==='PM-101'?'Explore impact path':'Inspect evidence')+' <span aria-hidden="true">↗</span></button><button id="ask-rovo" class="button ghost" aria-expanded="'+state.rovo+'">'+(state.rovo?'Hide sample explanation':'Ask Rovo · sample')+'</button></div>'+rovo+'</div>';
el('detail-impact').addEventListener('click',function(){setView(c.id==='PM-101'?'map':'evidence');});
el('ask-rovo').addEventListener('click',function(){state.rovo=!state.rovo;renderDetail();el('ask-rovo').focus();});
}
function renderLifecycle(){
var phase=data.lifecycle.find(function(p){return p.id===state.selectedPhase;})||data.lifecycle[3];
var currentRevision=phase.id==='definition'&&state.requirementChanged?'4':phase.revision;
var phaseIndex=data.lifecycle.indexOf(phase)+1;
var cards=data.lifecycle.map(function(p,i){var on=p.id===phase.id;return '<button class="phase-card '+(on?'selected':'')+'" data-phase="'+p.id+'" aria-pressed="'+on+'"><span class="phase-number">'+String(i+1).padStart(2,'0')+'</span><span><strong>'+esc(p.title)+'</strong><small>'+esc(p.artifact)+'</small></span></button>';}).join('');
el('view-content').innerHTML='<div class="panel-header"><h2>Product lifecycle</h2><p>Ten connected phases. Teams can revisit or overlap them.</p></div><div class="lifecycle-content"><div class="context-summary"><span class="node-type">PRODUCT DIRECTION</span><strong>Reliable self-service activation</strong><p>Merchant Experience · Jon Bell, product owner</p><p>Initiative: Self-service activation · Maya Chen</p></div><div class="phase-grid" aria-label="Choose a lifecycle phase">'+cards+'</div><section class="phase-detail" aria-labelledby="phase-detail-title"><span class="small-label">PHASE '+phaseIndex+' · EXAMPLE CONFLUENCE ARTIFACT</span><h3 id="phase-detail-title">'+esc(phase.title)+'</h3><p>'+esc(phase.description)+'</p><dl class="phase-facts"><div><dt>Coordinator</dt><dd>'+esc(people[phase.owner].name)+'</dd></div><div><dt>Source artifact</dt><dd>'+esc(phase.artifact)+'</dd></div><div><dt>Current source</dt><dd>Example version '+currentRevision+'</dd></div></dl><p class="small-label">WHAT READINESS REQUIRES</p><p>'+esc(phase.criterion)+'</p></section><section class="gate-card" aria-label="Example requirement and readiness"><div class="gate-top"><strong>REQ-07 · Activation integrity</strong><span class="status '+(state.requirementChanged?'WATCH':'UNKNOWN')+'">'+(state.requirementChanged?'◷ Reassess':'? Evidence pending')+'</span></div><p>One activation per merchant request. Linked to epic MX-100, story MX-110, and task MX-121.</p><p><strong>Mapped PRD v3 → current v'+(state.requirementChanged?'4':'3')+'.</strong> '+(state.requirementChanged?'The changed requirement includes retried callbacks. The previous gate basis is stale.':'Production and designated acceptance evidence are still required for release readiness.')+'</p><p class="gate-boundary">Gate readiness, execution authority, and a verified business outcome are separate states.</p><div class="lifecycle-actions"><button class="button secondary" id="simulate-prd">'+(state.requirementChanged?'Reset example PRD':'Simulate PRD change')+'</button><button class="button primary" id="lifecycle-trace">Follow the work trace →</button></div></section></div>';
document.querySelectorAll('[data-phase]').forEach(function(b){b.addEventListener('click',function(){state.selectedPhase=b.dataset.phase;renderLifecycle();document.querySelector('[data-phase="'+state.selectedPhase+'"]').focus();});});
el('lifecycle-trace').addEventListener('click',function(){state.selected='PM-101';setView('map');});
el('simulate-prd').addEventListener('click',function(){state.requirementChanged=!state.requirementChanged;state.sourceRevision++;render();el('simulate-prd').focus();toast(state.requirementChanged?'Example PRD changed. Requirement and gate applicability need reassessment.':'Example PRD restored. Existing proposals may still need a fresh review.');});
}
function renderMap(){
var native=state.hierarchy==='native';
var higher=native?'<button class="graph-node planning" data-node="program"><span class="node-type">PROGRAM · MX-1 · CUSTOM LEVEL 3</span><strong>Merchant growth</strong><small>Jon Bell · configured higher level in this example</small></button><div class="hierarchy-line">native parent of</div><button class="graph-node planning" data-node="initiative"><span class="node-type">INITIATIVE · MX-10 · CUSTOM LEVEL 2</span><strong>Self-service activation</strong><small>Maya Chen · initiative owner</small></button><div class="hierarchy-line">native parent of</div>':'<button class="graph-node planning" data-node="initiative"><span class="node-type">CONFLUENCE INITIATIVE · PLANNING CONTEXT</span><strong>Self-service activation</strong><small>Maya Chen · no native above-epic level in this example</small></button><div class="hierarchy-line planning-link">epic supports initiative · planning link</div>';
el('view-content').innerHTML='<div class="panel-header"><h2>Direction to delivery</h2><p>Planning, native hierarchy, and dependencies have distinct relationships.</p></div><div class="map-content"><div class="hierarchy-control"><label for="hierarchy-mode">Example hierarchy</label><select id="hierarchy-mode"><option value="native">Configured Program / Initiative levels</option><option value="planning">No higher levels · planning links</option></select></div><div class="context-summary"><span class="node-type">PRODUCT GOAL · PLANNING CONTEXT</span><strong>Reliable self-service activation</strong><p>Merchant Experience · linked to the initiative</p><button id="map-lifecycle" class="text-button">Inspect lifecycle and PRD →</button></div><div class="project-scope">Jira project container: <strong>Merchant Experience</strong></div>'+higher+'<button class="graph-node epic" data-node="epic"><span class="node-type">EPIC · MX-100 · LEVEL 1</span><strong>Merchant launch</strong><small>Defined by PRD v3 · REQ-07</small></button><div class="hierarchy-line">parent of all three standard work items</div><div class="work-branches three"><div><button class="graph-node" data-node="story"><span class="node-type">STORY · MX-110</span><strong>Activate a merchant once</strong><small>Jon Bell · Product owner</small></button><p class="branch-note">REQ-07 defines the acceptance condition.</p></div><div><button class="graph-node task" data-node="task"><span class="node-type">TASK · MX-121</span><strong>Enable production onboarding</strong><small>Leah Ortiz · Team lead</small></button><div class="hierarchy-line">native parent of</div><button class="graph-node" data-node="subtask"><span class="node-type">SUBTASK · MX-122</span><strong>Confirm tenant configuration</strong><small>Owen Reed · Done</small></button></div><div><button class="graph-node '+(state.delayed?'bug':'')+'" data-node="bug"><span class="node-type">BUG · MX-137</span><strong>Duplicate onboarding events</strong><small>Owen Reed · '+(state.delayed?'Reopened':'Resolved')+'</small></button><p class="branch-note">Blocks MX-121 through a dependency link.</p></div></div><div class="relationship-note">Task <strong>implements</strong> story · Bug <strong>blocks</strong> task. All three are hierarchy peers.</div><div class="hierarchy-line">task supports the commitment</div><button class="graph-node outcome" data-node="commitment"><span class="node-type">COMMITMENT · PM-101</span><strong>Launch merchant onboarding</strong><small>Northstar Retail · agreed 20 Nov, 17:00 Stockholm</small></button><div class="map-note">'+(state.delayed?'<strong>Observed impact:</strong> the unresolved bug target falls four days after the promise. The promise has not been renegotiated.':state.requirementChanged?'<strong>Source drift:</strong> current PRD v4 differs from mapped v3. Reassess requirement and release-readiness applicability.':'<strong>Try the scenario:</strong> simulate a reopened bug or change the example PRD from the lifecycle view.')+'</div><div class="path-section"><h3>Accessible impact path</h3><ol class="path-list"><li>MX-137 <strong>blocks</strong> MX-121.</li><li>MX-121 <strong>implements</strong> story MX-110 and <strong>supports</strong> PM-101.</li><li>REQ-07 <strong>defines</strong> the linked work and acceptance conditions.</li><li>Epic MX-100 '+(native?'has native parent initiative MX-10.':'supports the Confluence initiative through a planning link.')+'</li><li>The initiative <strong>aligns to</strong> the product objective.</li><li>Maya is accountable; Leah coordinates delivery; Owen owns the bug.</li></ol><button id="map-recovery" class="button primary" '+(!state.delayed?'disabled':'')+'>Prepare example recovery</button>'+(!state.delayed?'<p class="row-sub">Simulate the dependency delay to prepare the due-date recovery example.</p>':'')+'</div></div>';
el('hierarchy-mode').value=state.hierarchy;
el('hierarchy-mode').addEventListener('change',function(e){state.hierarchy=e.target.value;renderMap();el('hierarchy-mode').focus();});
el('map-lifecycle').addEventListener('click',function(){state.selectedPhase='definition';setView('lifecycle');});
document.querySelectorAll('[data-node]').forEach(function(b){b.classList.toggle('node-selected',b.dataset.node===state.selectedNode);b.addEventListener('click',function(){state.selectedNode=b.dataset.node;state.selected='PM-101';state.rovo=b.dataset.node==='bug';renderMap();renderDetail();document.querySelector('[data-node="'+state.selectedNode+'"]').focus();});});
el('map-recovery').addEventListener('click',prepareReview);
}
function prepareReview(){
state.selected='PM-101';state.proposal={sourceRevision:state.sourceRevision,from:'2026-11-19',to:'2026-11-24'};state.reviewed=false;
render();showReview();
}
function showReview(){
var stale=state.proposal.sourceRevision!==state.sourceRevision;
el('review-body').innerHTML='<p class="dialog-intro">Target: <strong>MX-121 · Enable production onboarding</strong>. This example changes the engineering target, not the customer commitment.</p><div class="review-diff"><div><small>CURRENT TARGET</small><strong>'+date(state.proposal.from)+'</strong></div><span aria-hidden="true">→</span><div><small>PROPOSED TARGET</small><strong>'+date(state.proposal.to)+'</strong></div></div><div class="review-disclaimer"><strong>The promise remains 20 Nov.</strong><br>A later engineering target does not renegotiate the customer agreement. The delivery risk remains visible.</div><p class="dialog-intro">In the implemented product, a recorded review is followed by a fresh permission/source check, Decionis authorization, controlled execution, and result verification.</p>'+(stale?'<div class="form-error" role="alert">The example source changed. Prepare a fresh proposal.</div>':'')+'<p class="row-sub">This prototype records a local example review only. Nothing is sent to Jira, Decionis, or a customer.</p>';
el('record-review').disabled=stale||state.reviewed;
el('record-review').textContent=state.reviewed?'Example review recorded':'Record example review';
el('review-dialog').showModal();
}
function renderReviews(){
var body='<div class="panel-header"><h2>Review queue</h2><p>Current proposals, their evidence, and the precise requested effect.</p></div>';
if(!state.proposal)body+='<div class="empty"><div class="change-icon" style="margin:0 auto 14px">✓</div><h3>No example review is waiting.</h3><p>Simulate a dependency delay, then prepare a recovery proposal from the work map.</p><button id="reviews-map" class="button secondary">Open work map</button></div>';
else body+='<div class="review-card"><span class="status '+(state.reviewed?'REVIEWED':'WATCH')+'">'+(state.reviewed?'✓ Review recorded':'◷ Awaiting example review')+'</span><h3>Update the engineering target</h3><p>MX-121 · '+date(state.proposal.from)+' → '+date(state.proposal.to)+'</p><p>The PM-101 promise remains unchanged. '+(state.proposal.sourceRevision!==state.sourceRevision?'The source has changed; prepare a new proposal.':'Source revision matches this example proposal.')+'</p><button id="open-review" class="button secondary">Inspect exact change</button><button id="fresh-review" class="text-button" style="margin-left:14px">Prepare fresh proposal</button></div>';
el('view-content').innerHTML=body;
if(el('reviews-map'))el('reviews-map').addEventListener('click',function(){setView('map');});
if(el('open-review'))el('open-review').addEventListener('click',showReview);
if(el('fresh-review'))el('fresh-review').addEventListener('click',function(){if(!state.delayed){toast('Simulate a changed dependency before preparing recovery.');return;}prepareReview();});
}
function renderEvidence(){
el('view-content').innerHTML='<div class="panel-header"><h2>Evidence and coverage</h2><p>Source records establish context; verification establishes the agreed outcome.</p></div><div class="source-card"><span class="status '+(state.delayed?'AT_RISK':'ON_TRACK')+'">'+(state.delayed?'Changed source':'Source checked')+'</span><h3>MX-137 · Duplicate onboarding events</h3><p>'+ (state.delayed?'The example bug was reopened. Its target is now 24 Nov and the linked launch commitment is at risk.':'The example bug is resolved. Required production and customer acceptance evidence are still separate.')+'</p><div class="source-meta"><span>Source: example Jira record</span><span>Revision '+state.sourceRevision+'</span></div><button class="button secondary small" id="evidence-map">Inspect impact path</button></div><div class="source-card"><span class="status UNKNOWN">? Context incomplete</span><h3>Support handover acceptance</h3><p>The support owner has not supplied a current acceptance record. Promisory cannot mark the handover fulfilled.</p><div class="source-meta"><span>PM-103</span><span>No qualifying current evidence</span></div></div><div class="source-card"><span class="status FULFILLED">✓ Outcome verified</span><h3>Settlement status page</h3><p>The designated owner verified the example outcome on 17 Nov. This fixture illustrates the evidence state; it is not a live verification.</p><div class="source-meta"><span>PM-104</span><span>On time</span></div></div>';
el('evidence-map').addEventListener('click',function(){state.selected='PM-101';setView('map');});
}
document.querySelectorAll('[data-view]').forEach(function(b){b.addEventListener('click',function(){setView(b.dataset.view);});});
el('persona').addEventListener('change',function(e){state.role=e.target.value;state.view='overview';state.search='';state.filter='all';state.selected='PM-101';render();});
el('simulate').addEventListener('click',function(){state.delayed=!state.delayed;state.sourceRevision++;state.commitments.find(function(c){return c.id==='PM-101';}).health=state.delayed?'AT_RISK':'WATCH';render();toast(state.delayed?'Example updated: the bug now threatens the launch.':'Example source reset. Existing reviews may be stale.');});
el('new-commitment').addEventListener('click',function(){el('form-error').hidden=true;document.querySelectorAll('#commitment-form [aria-invalid]').forEach(function(x){x.removeAttribute('aria-invalid');});el('commitment-dialog').showModal();el('commit-title').focus();});
document.querySelectorAll('.close-dialog').forEach(function(b){b.addEventListener('click',function(){b.closest('dialog').close();});});
el('commitment-form').addEventListener('submit',function(e){
e.preventDefault();var fields=[['commit-title','Describe the commitment.'],['commit-owner','Choose one accountable owner.'],['commit-beneficiary','Name the beneficiary.'],['commit-date','Choose a due date.'],['commit-time','Choose a cutoff time.'],['commit-acceptance','Add measurable acceptance conditions.']];
var invalid=[];fields.forEach(function(f){var x=el(f[0]);var bad=!x.value.trim()||!x.validity.valid;x.setAttribute('aria-invalid',String(bad));if(bad)invalid.push(f);});
if(invalid.length){el('form-error').textContent=invalid.map(function(f){return f[1];}).join(' ');el('form-error').hidden=false;el(invalid[0][0]).focus();return;}
var id='PM-'+(101+state.commitments.length);state.commitments.push({id:id,title:el('commit-title').value.trim(),owner:el('commit-owner').value,beneficiary:el('commit-beneficiary').value.trim(),dueDate:el('commit-date').value,cutoffTime:el('commit-time').value,timeZone:el('commit-zone').value,watching:el('watch-draft').checked,lifecycle:'DRAFT',health:'UNKNOWN',coverage:'INCOMPLETE',workIds:[],acceptance:el('commit-acceptance').value.trim()});
state.selected=id;state.role='manager';el('persona').value='manager';state.search='';state.filter='all';state.view='overview';el('commitment-dialog').close();el('commitment-form').reset();render();toast('Example draft added. Owner acceptance is still required.');
});
el('record-review').addEventListener('click',function(){if(!state.proposal||state.proposal.sourceRevision!==state.sourceRevision){toast('The source changed. Prepare a new example proposal.');return;}state.reviewed=true;el('review-dialog').close();state.view='reviews';render();toast('Example review recorded locally. No external action occurred.');});
el('review-dialog').addEventListener('close',function(){requestAnimationFrame(function(){var target=state.view==='reviews'?el('open-review'):state.view==='map'?el('map-recovery'):document.querySelector('.nav-item.active');if(target)target.focus();});});
el('commitment-dialog').addEventListener('close',function(){requestAnimationFrame(function(){el('new-commitment').focus();});});
render();
})();
